{
  "implementation": "def solve(case):
    nodes = case['nodes']
    core_distance = case['core_distance']
    distances = case['distances']

    # Build edges with mutual reachability
    edges = []
    for u, v, d in distances:
        mut_reach = max(core_distance[u], core_distance[v], d)
        # canonicalize: ensure u < v (lexicographic)
        if u > v:
            u, v = v, u
        edges.append((mut_reach, u, v))

    # Sort by weight, then u, then v
    edges.sort()

    # Union-Find structures
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    required_edges = len(nodes) - 1

    for weight, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, weight])
            total_weight += weight
            if len(mst_edges) == required_edges:
                break

    if len(mst_edges) != required_edges:
        raise ValueError("Input graph is disconnected, cannot form MST")

    return {
        "mst_edges": mst_edges,
        "total_weight": total_weight
    }"
}
